-- MEDICAL only. Restore missing archive policies while requiring active organization membership.
begin;
do $guard$ begin
 if exists(select 1 from pg_policies where schemaname='public' and tablename in ('bf_owner_report_branding','bf_owner_report_runs','bf_owner_report_events')) then raise exception 'Review existing policies before applying this one-time repair'; end if;
 if exists(select 1 from pg_class where oid in ('public.bf_owner_report_branding'::regclass,'public.bf_owner_report_runs'::regclass,'public.bf_owner_report_events'::regclass) and not relrowsecurity) then raise exception 'RLS must remain enabled'; end if;
end $guard$;
create policy bf_owner_report_branding_read on public.bf_owner_report_branding for select to authenticated using (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_branding.organization_id and u.user_id=(select auth.uid()) and u.is_active));
create policy bf_owner_report_branding_insert on public.bf_owner_report_branding for insert to authenticated with check (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_branding.organization_id and u.user_id=(select auth.uid()) and u.is_active) and (contract_id is null or exists(select 1 from public.bf_contracts c where c.id=bf_owner_report_branding.contract_id and c.organization_id=bf_owner_report_branding.organization_id)));
create policy bf_owner_report_branding_update on public.bf_owner_report_branding for update to authenticated using (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_branding.organization_id and u.user_id=(select auth.uid()) and u.is_active)) with check (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_branding.organization_id and u.user_id=(select auth.uid()) and u.is_active) and (contract_id is null or exists(select 1 from public.bf_contracts c where c.id=bf_owner_report_branding.contract_id and c.organization_id=bf_owner_report_branding.organization_id)));
grant select,insert,update on public.bf_owner_report_branding to authenticated;
create policy bf_owner_report_runs_read on public.bf_owner_report_runs for select to authenticated using (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_runs.organization_id and u.user_id=(select auth.uid()) and u.is_active));
create policy bf_owner_report_runs_insert on public.bf_owner_report_runs for insert to authenticated with check (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_runs.organization_id and u.user_id=(select auth.uid()) and u.is_active) and (contract_id is null or exists(select 1 from public.bf_contracts c where c.id=bf_owner_report_runs.contract_id and c.organization_id=bf_owner_report_runs.organization_id)));
create policy bf_owner_report_runs_update on public.bf_owner_report_runs for update to authenticated using (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_runs.organization_id and u.user_id=(select auth.uid()) and u.is_active)) with check (public.bf4_staff(organization_id,'reports.view') and exists (select 1 from public.bf_acl_user_organizations u where u.organization_id = bf_owner_report_runs.organization_id and u.user_id=(select auth.uid()) and u.is_active) and (contract_id is null or exists(select 1 from public.bf_contracts c where c.id=bf_owner_report_runs.contract_id and c.organization_id=bf_owner_report_runs.organization_id)));
grant select,insert,update on public.bf_owner_report_runs to authenticated;
create policy bf_owner_report_events_read on public.bf_owner_report_events for select to authenticated using (exists(select 1 from public.bf_owner_report_runs r join public.bf_acl_user_organizations u on u.organization_id=r.organization_id where r.id=bf_owner_report_events.report_run_id and u.user_id=(select auth.uid()) and u.is_active and public.bf4_staff(r.organization_id,'reports.view')));
create policy bf_owner_report_events_insert on public.bf_owner_report_events for insert to authenticated with check (exists(select 1 from public.bf_owner_report_runs r join public.bf_acl_user_organizations u on u.organization_id=r.organization_id where r.id=bf_owner_report_events.report_run_id and u.user_id=(select auth.uid()) and u.is_active and public.bf4_staff(r.organization_id,'reports.view')) and (actor_id is null or actor_id=(select auth.uid())));
grant select,insert on public.bf_owner_report_events to authenticated;
notify pgrst,'reload schema';
commit;

